// ---------- Menu: sala de monitoramento escura. Fundo = imagem de referência; telas (ruído, glitch), REC, LEDs e a luz das TVs piscando são animados por cima. Passa pelo mesmo pós-processamento da câmera do jogador ----------
const menuScene=new THREE.Scene();menuScene.background=new THREE.Color(0x000000);
const menuCam=new THREE.PerspectiveCamera(40,1,.1,60);menuCam.position.set(0,0,7);
const TVW=1291,TVH=724;
const tvG=new THREE.Group(),tvIn=new THREE.Group();tvG.add(tvIn);menuScene.add(tvG); // tvIn: 1 unidade = 1 pixel da imagem (x p/ direita, y = -linha)
const tvImg=new Image(),bgTex=new THREE.Texture(tvImg);
bgTex.minFilter=bgTex.magFilter=THREE.LinearFilter;bgTex.generateMipmaps=false;
tvImg.onload=()=>{bgTex.needsUpdate=true};
tvImg.src='data:image/jpeg;base64,';
const bgMat=new THREE.MeshBasicMaterial({map:bgTex,color:0xeeeeee,depthTest:false,depthWrite:false});const BG_GAIN=2.5; // brilho da imagem de fundo (multiplicador; antes 1.0)
{const m=new THREE.Mesh(new THREE.PlaneGeometry(TVW,TVH),bgMat);m.position.set(TVW/2,-TVH/2,0);m.renderOrder=0;tvIn.add(m);}
{ // bordas de cima e de baixo da imagem esmaecem para o preto (aparecem no retrato e em telas quadradas)
  const c=document.createElement('canvas');c.width=4;c.height=64;const g=c.getContext('2d'),gr=g.createLinearGradient(0,0,0,64);
  gr.addColorStop(0,'rgba(0,0,0,1)');gr.addColorStop(.45,'rgba(0,0,0,.55)');gr.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=gr;g.fillRect(0,0,4,64);
  const t=new THREE.CanvasTexture(c);t.minFilter=t.magFilter=THREE.LinearFilter;t.generateMipmaps=false;
  const mt=new THREE.MeshBasicMaterial({map:t,transparent:true,depthTest:false,depthWrite:false});
  [[0,0],[1,Math.PI]].forEach(([b,r])=>{const e=new THREE.Mesh(new THREE.PlaneGeometry(TVW,80),mt);e.position.set(TVW/2,b?-(TVH-40):-40,0);e.rotation.z=r;e.renderOrder=1;tvIn.add(e)});
}
const faceT=(()=>{const c=document.createElement('canvas');c.width=128;c.height=96;const g=c.getContext('2d');
  g.fillStyle='#050706';g.fillRect(0,0,128,96);
  const gr=g.createRadialGradient(64,44,4,64,48,40);gr.addColorStop(0,'#dfe3d6');gr.addColorStop(1,'#59604f');
  g.fillStyle=gr;g.beginPath();g.ellipse(64,48,23,37,0,0,6.2832);g.fill();
  g.fillStyle='#000';g.beginPath();g.ellipse(53,40,6,10,.15,0,6.2832);g.fill();g.beginPath();g.ellipse(75,40,6,10,-.15,0,6.2832);g.fill();
  g.beginPath();g.ellipse(64,70,6,13,0,0,6.2832);g.fill();
  g.fillStyle='rgba(255,255,255,.85)';g.fillRect(52,37,2,2);g.fillRect(74,37,2,2);
  g.fillStyle='rgba(0,0,0,.3)';for(let y=0;y<96;y+=3)g.fillRect(0,y,128,1);
  const t=new THREE.CanvasTexture(c);t.minFilter=t.magFilter=THREE.NearestFilter;t.generateMipmaps=false;return t})();
// telas: o shader amostra a própria imagem de fundo (feeds das câmeras) ou gera chiado (telas fora do ar)
const tvVS='varying vec2 vQ,vI;void main(){vQ=uv;vI=vec2(position.x/1291.,1.+position.y/724.);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}';
const tvFS=`varying vec2 vQ,vI;uniform sampler2D uBg,uFace;uniform float uT,uMode,uLv,uGl,uPh,uScare,uFps;uniform vec2 uRes;
float h(vec2 p){return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);}
void main(){
  vec2 q=abs(vQ-.5)*2.;
  float e=pow(pow(q.x,5.)+pow(q.y,5.),.2);
  float m=1.-smoothstep(.84,1.,e);
  vec3 c;
  if(uMode<.5||uMode>2.5){
    float band=h(vec2(floor(vQ.y*uRes.y*.12),floor(uT*18.)));
    float dx=(band-.5)*uGl*.012*step(.55,band);
    vec2 uv=vec2(vI.x+dx,vI.y);
    float ca=.0009*(1.+uGl*3.);
    c=vec3(texture2D(uBg,uv+vec2(ca,0.)).r,texture2D(uBg,uv).g,texture2D(uBg,uv-vec2(ca,0.)).b);
    float bar=fract(vQ.y-uT*.11+uPh);
    c*=1.+.2*smoothstep(0.,.05,bar)*(1.-smoothstep(.05,.22,bar));
    c*=.94+.06*sin(vQ.y*uRes.y*1.9+uT*6.);
    c+=(h(vQ*uRes+fract(uT)*91.)-.5)*(.012+.1*dot(c,vec3(.33))+uGl*.22);
    c*=uLv;
  }else{
    float fr=floor(uT*uFps);
    float v;
    if(uMode<1.5){
      vec2 p=vQ*uRes;
      float f1=h(floor(p*.8)+fr*vec2(17.,31.));
      vec2 pp=p*.15+fr*vec2(3.1,1.7),ii=floor(pp),ff=fract(pp);ff=ff*ff*(3.-2.*ff);
      float n2=mix(mix(h(ii),h(ii+vec2(1.,0.)),ff.x),mix(h(ii+vec2(0.,1.)),h(ii+vec2(1.,1.)),ff.x),ff.y);
      v=smoothstep(.06,1.,mix(f1,n2,.62));
    }else{
      float row=floor(vQ.y*uRes.y*.6);
      float rn=h(vec2(row,fr));
      float n=h(vec2(floor(vQ.x*uRes.x*(.03+.22*rn)+rn*50.),row+fr*3.));
      v=.2+.1*h(vec2(row*.5,fr))+.95*n*n*n*n;
    }
    c=vec3(.72,.82,1.)*v*uLv;
    c*=1.-.3*smoothstep(.5,1.,e);
    if(uScare>.5)c=texture2D(uFace,vQ).rgb*vec3(.85,.95,1.)*uLv*1.1;
  }
  gl_FragColor=vec4(c,m);
}`;
function tvQuad(c,mat){ // c = TLx,TLy,TRx,TRy,BRx,BRy,BLx,BLy em pixels da imagem
  const g=new THREE.BufferGeometry();
  g.setAttribute('position',new THREE.Float32BufferAttribute([c[0],-c[1],0,c[2],-c[3],0,c[4],-c[5],0,c[6],-c[7],0],3));
  g.setAttribute('uv',new THREE.Float32BufferAttribute([0,1,1,1,1,0,0,0],2));
  g.setIndex([0,3,2,0,2,1]);
  const m=new THREE.Mesh(g,mat);m.frustumCulled=false;m.renderOrder=3;tvIn.add(m);return m}
const TV_SCR=[ // m: 0 = câmera, 1 = chiado de pontos, 2 = chiado em linhas, 3 = NO SIGNAL
  {m:1,q:[244,101,353,102,352,188,246,183],r:[110,86],fps:22,b:.9,j:.2},
  {m:0,q:[433,123,615,138,618,263,437,259],r:[185,140],b:1,j:.05,ph:.3},   // CH 02
  {m:3,q:[241,224,410,224,410,331,241,331],r:[170,107],b:1,j:.03,ph:.5},   // NO SIGNAL
  {m:0,q:[577,290,712,291,712,376,579,377],r:[135,86],b:1,j:.06,ph:.7},    // CH 03
  {m:0,q:[201,393,494,386,496,578,207,611],r:[293,215],b:1,j:.04,ph:.1},   // CH 01
  {m:2,q:[583,433,766,426,768,562,586,577],r:[184,145],fps:26,b:.9,j:.2}   // linhas estouradas
];
for(const s of TV_SCR){
  s.mt=new THREE.ShaderMaterial({uniforms:{uBg:{value:bgTex},uFace:{value:faceT},uT:{value:0},uMode:{value:s.m},uLv:{value:1},uGl:{value:0},uPh:{value:s.ph||0},uScare:{value:0},uFps:{value:s.fps||25},uRes:{value:new THREE.Vector2(s.r[0],s.r[1])}},
    vertexShader:tvVS,fragmentShader:tvFS,transparent:true,depthTest:false,depthWrite:false,side:THREE.DoubleSide});
  tvQuad(s.q,s.mt);s.gl=0;s.lv=1;}
function radTex(sz,stops){const c=document.createElement('canvas');c.width=c.height=sz;const g=c.getContext('2d'),r=g.createRadialGradient(sz/2,sz/2,0,sz/2,sz/2,sz/2);
  stops.forEach(([o,col])=>r.addColorStop(o,col));g.fillStyle=r;g.fillRect(0,0,sz,sz);const t=new THREE.CanvasTexture(c);t.minFilter=t.magFilter=THREE.LinearFilter;t.generateMipmaps=false;return t}
const glowT=radTex(64,[[0,'rgba(255,255,255,1)'],[.35,'rgba(255,255,255,.45)'],[1,'rgba(255,255,255,0)']]);
const dotT=radTex(32,[[0,'rgba(255,205,195,1)'],[.3,'rgba(255,40,40,1)'],[.55,'rgba(255,20,20,.5)'],[1,'rgba(255,0,0,0)']]);
function tvPlane(tex,x,y,w,h,col,blend,ro){
  const mt=new THREE.MeshBasicMaterial({map:tex,color:col,transparent:true,opacity:0,blending:blend,depthTest:false,depthWrite:false});
  const m=new THREE.Mesh(new THREE.PlaneGeometry(w,h),mt);m.position.set(x,-y,0);m.renderOrder=ro;tvIn.add(m);return mt}
// luz que cada tela joga no ambiente (pisca junto com a tela que a comanda): x, y, largura, altura, cor, opacidade base, índice da tela
const TV_GL=[
  [298,145,300,230,0x9db4e8,.10,0],[525,195,520,400,0x9db8ee,.09,1],[326,277,420,300,0x9db0e0,.04,2],[645,333,380,260,0x9fb9f0,.09,3],
  [350,498,780,560,0xa5bef5,.12,4],[675,502,460,360,0x9fb4e8,.08,5],[360,655,520,120,0x8fb0ff,.09,4],[900,200,520,640,0x8aa0d0,.035,1]
].map(([x,y,w,h,c,o,s])=>({mt:tvPlane(glowT,x,y,w,h,c,THREE.AdditiveBlending,2),o,s}));
const redG=tvPlane(glowT,480,160,1500,900,0xff2010,THREE.AdditiveBlending,6);
const TV_REC=[[481.7,405,18,0],[702.7,301.3,13,.5]].map(([x,y,s,ph])=>({mt:tvPlane(dotT,x,y,s,s,0xffffff,THREE.NormalBlending,7),ph}));
const TV_LED=[[354,200],[410.5,340.5],[714,389],[505.7,617.4],[768.5,575.7],[580,101]].map(([x,y],i)=>({mt:tvPlane(dotT,x,y,9,9,0xffffff,THREE.AdditiveBlending,7),i}));
let nextScare=3,scareEnd=0,menuScare=false,MENU_ON=false,nextDip=1.5,dipEnd=0;
function tvTick(t){
  const sc=false;menuScare=false; // sem susto: as telas fora do ar ficam só com chiado
  if(t>=nextDip){dipEnd=t+.06+Math.random()*.22;nextDip=dipEnd+2+Math.random()*5;}      // oscilação de energia: as luzes tremem juntas
  const dip=t<dipEnd?(Math.random()<.55?.2+Math.random()*.5:1.12):1;
  bgMat.color.setScalar((.9+.04*Math.sin(t*9)+(Math.random()-.5)*.05)*(.55+.45*dip)*BG_GAIN);
  for(let i=0;i<TV_SCR.length;i++){
    const s=TV_SCR[i],u=s.mt.uniforms,st=s.m===1||s.m===2;
    s.gl*=.86;if(!st&&Math.random()<.006)s.gl=1;
    let lv=s.b*(1+.05*Math.sin(t*(6+i*1.7)+i*2)+(Math.random()-.5)*(.06+s.j))*dip;
    if(sc)lv*=st?1.25:(Math.random()<.5?.35:1);
    s.lv=lv;u.uT.value=t;u.uLv.value=lv;u.uGl.value=s.gl+(sc&&!st?.7:0);u.uScare.value=sc&&st?1:0;
  }
  for(const g of TV_GL)g.mt.opacity=Math.max(0,g.o*TV_SCR[g.s].lv*(1+(Math.random()-.5)*.25));
  redG.opacity=sc?.2+Math.random()*.12:0;
  for(const r of TV_REC)r.mt.opacity=((t*.9+r.ph)%2<1)?1:0;
  for(const l of TV_LED)l.mt.opacity=((t*(1.2+l.i*.23)+l.i*.37)%1<.55)?.85:.2;
}
const MS={x:0,y:0,r:0};
function menuCamSway(t){ // fundo das TVs fica parado; só a interface balança (mão tremendo / respiração)
  menuCam.position.set(0,0,7);menuCam.rotation.set(0,0,0);
  const h=innerHeight,ppr=h/(2*Math.tan(20*Math.PI/180)),ppu=ppr/7,st=document.documentElement.style;
  const cx=.035*Math.sin(t*.7)+.01*Math.sin(t*3.1),cy=.025*Math.sin(t*1.1)+.008*Math.sin(t*4.3);
  const rx=.005*Math.sin(t*.9),ry=.006*Math.sin(t*.6),rz=.01*Math.sin(t*.4);
  MS.x=ry*ppr-cx*ppu;MS.y=rx*ppr+cy*ppu;MS.r=rz;
  st.setProperty('--mx',(ry*ppr-cx*ppu).toFixed(2)+'px');
  st.setProperty('--my',(rx*ppr+cy*ppu).toFixed(2)+'px');
  st.setProperty('--mr',(rz*57.2958).toFixed(3)+'deg');}
function fitMenuCam(a){menuCam.aspect=a;menuCam.updateProjectionMatrix();
  const hh=Math.tan(20*Math.PI/180)*7;let vw,cx,cy;
  // "cover": a imagem sempre preenche a tela (sem faixas pretas) em qualquer proporção
  vw=Math.min(TVW,TVH*a);                       // largura visível da imagem, em pixels da imagem
  const x0=a>=1.15?130:480;                      // paisagem: TVs à esquerda (UI à direita); retrato: foco nas TVs
  cx=Math.max(vw/2,Math.min(TVW-vw/2,a>=1.15?x0+vw/2:x0));cy=TVH/2;
  const gs=2*hh/(vw/a);
  tvG.scale.setScalar(gs);tvG.position.set(-gs*cx,gs*cy,0);}
let menuWas=false;

