function noiseTex(base, amt, rep){
  const s=128, cv=document.createElement('canvas'); cv.width=cv.height=s;
  const g=cv.getContext('2d'), im=g.createImageData(s,s);
  for(let i=0;i<s*s;i++){const v=base+(Math.random()-.5)*amt; im.data[i*4]=v;im.data[i*4+1]=v;im.data[i*4+2]=v;im.data[i*4+3]=255;}
  g.putImageData(im,0,0); g.strokeStyle='rgba(0,0,0,.35)'; g.strokeRect(0,0,s,s);
  const t=texQ(new THREE.CanvasTexture(cv)); t.wrapS=t.wrapT=THREE.RepeatWrapping; t.repeat.set(rep,rep); return t;
}
