const floor=new THREE.Mesh(new THREE.PlaneGeometry(840,580),new THREE.MeshStandardMaterial({map:(t=>{t.repeat.set(420,290);return t})(noiseTex(120,60,1)),color:0x7d8566,roughness:.95}));
floor.rotation.x=-Math.PI/2; floor.position.set(110,0,0); scene.add(floor);

