function addBox(x,z,w,d,h,mat,y0=0){
  const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);
  m.position.set(x,y0+h/2,z); scene.add(m); hitMeshes.push(m);
  solids.push({minX:x-w/2,maxX:x+w/2,minZ:z-d/2,maxZ:z+d/2});
}
const crateMat=new THREE.MeshStandardMaterial({map:noiseTex(110,70,1),color:0x8a6a42,roughness:.9});
let seed=7; const rnd=()=> (seed=(seed*16807)%2147483647)/2147483647;
